1	import 'dart:async';
2	
3	import 'package:flutter_bloc/flutter_bloc.dart';
4	
5	import '../../../../core/failure/failure.dart';
6	import '../../domain/entities/export_download_format.dart';
7	import '../../domain/entities/export_job_state.dart';
8	import '../../domain/repositories/export_repository.dart';
9	import '../../domain/services/download_opener.dart';
10	
11	/// Drives `ExportStatusSheet` (spec-7-1) — a fresh, `get_it`-factory-
12	/// scoped instance per download-icon tap (Code Map: the `registerFactory`
13	/// one-shot-cubit precedent set by `TextEntryCubit`), closed by the call
14	/// site itself once done with it (`MeusRegistrosScreen`'s own export handler/
15	/// `ExportStatusSheet.show()`, mirroring `InsertionModal.show()`'s own
16	/// cubit-disposal convention), never by a `get_it` `dispose:` hook.
17	///
18	/// Starts in [ExportJobState.preparing] — the same visual the
19	/// `export-summary-create` 202 response's own `status: 'pending'` always
20	/// implies (`openapi.yaml`), so no separate "creating..." state is needed
21	/// before [start]'s own `createJob` call resolves.
22	class ExportJobCubit extends Cubit<ExportJobState> {
23	  ExportJobCubit(this._repository, this._downloadOpener)
24	    : super(const ExportJobState.preparing());
25	
26	  final ExportRepository _repository;
27	  final DownloadOpener _downloadOpener;
28	
29	  /// Design Notes — fixed poll cadence (docs/input is silent on this):
30	  /// the server job always reaches a terminal state, so no client
31	  /// timeout exists either.
32	  static const _pollInterval = Duration(seconds: 2);
33	
34	  /// Review finding (blind-hunter/edge-case-hunter layers) — a persistent
35	  /// `getStatus` failure (as opposed to one flaky blip) would otherwise
36	  /// poll forever with the sheet stuck on its last state and no visible
37	  /// indication anything is wrong. After this many *consecutive* failures,
38	  /// [_poll] gives up and surfaces the existing generic [ExportJobError]
39	  /// state instead — reusing the sheet's own already-built error visual
40	  /// rather than inventing a new one.
41	  static const _maxConsecutivePollFailures = 5;
42	
43	  String? _jobId;
44	  Timer? _pollTimer;
45	  int _consecutivePollFailures = 0;
46	
47	  /// Review finding (blind-hunter/edge-case-hunter layers) — `Timer.
48	  /// periodic` doesn't wait for one tick's own `_poll()` to finish before
49	  /// firing the next; without this guard, a `getStatus` call slower than
50	  /// [_pollInterval] could race a second, overlapping call, and a late,
51	  /// stale response landing after a newer terminal state was already
52	  /// emitted could "un-terminate" an already-finished job in the UI.
53	  bool _pollInFlight = false;
54	
55	  /// Creates the export job for [periodStart]/[periodEnd]
56	  /// (`export-summary-create`) and, on success, starts this cubit's own
57	  /// `Timer.periodic` poll loop against `export-status-get`.
58	  ///
59	  /// Returns `false` on a create failure (Boundaries: "Create fails →
60	  /// inline error, sheet never opens") — the same failure is also
61	  /// emitted as [ExportJobState.error] so the caller can read [state] for
62	  /// [Failure.message] without this method also having to hand back the
63	  /// raw `Failure` itself (the `Either<Failure, T>` shape, RNF09, is the
64	  /// repository's own contract, not every cubit method's).
65	  Future<bool> start({
66	    required DateTime periodStart,
67	    required DateTime periodEnd,
68	  }) async {
69	    final result = await _repository.createJob(
70	      periodStart: periodStart,
71	      periodEnd: periodEnd,
72	    );
73	    if (isClosed) {
74	      return false;
75	    }
76	    return result.match(
77	      (failure) {
78	        emit(ExportJobState.error(failure));
79	        return false;
80	      },
81	      (jobId) {
82	        _jobId = jobId;
83	        _startPolling();
84	        return true;
85	      },
86	    );
87	  }
88	
89	  void _startPolling() {
90	    _pollTimer?.cancel();
91	    _pollTimer = Timer.periodic(_pollInterval, (_) => _poll());
92	  }
93	
94	  Future<void> _poll() async {
95	    final jobId = _jobId;
96	    if (jobId == null || _pollInFlight || _isTerminal(state)) {
97	      return;
98	    }
99	    _pollInFlight = true;
100	    try {
101	      final result = await _repository.getStatus(jobId);
102	      if (isClosed || _isTerminal(state)) {
103	        return;
104	      }
105	      result.match(
106	        (failure) {
107	          // A transient poll failure (docs/input is silent on this) is
108	          // swallowed rather than surfaced, so one flaky network blip
109	          // never flips a still-running job to a false terminal error —
110	          // the next tick simply tries again. A *persistent* one gives up
111	          // after [_maxConsecutivePollFailures] instead of polling
112	          // forever.
113	          _consecutivePollFailures++;
114	          if (_consecutivePollFailures >= _maxConsecutivePollFailures) {
115	            _pollTimer?.cancel();
116	            emit(ExportJobState.error(failure));
117	          }
118	        },
119	        (newState) {
120	          _consecutivePollFailures = 0;
121	          emit(newState);
122	          if (_isTerminal(newState)) {
123	            _pollTimer?.cancel();
124	          }
125	        },
126	      );
127	    } finally {
128	      _pollInFlight = false;
129	    }
130	  }
131	
132	  bool _isTerminal(ExportJobState state) =>
133	      state is ExportJobDone ||
134	      state is ExportJobError ||
135	      state is ExportJobEmptyPeriod;
136	
137	  /// Review finding (code review, patch item 3), keyed by [format] —
138	  /// mirrors [_pollInFlight]: without this guard, a rapid double-tap on
139	  /// the *same* download button could fire two overlapping [_download]
140	  /// calls for it, each with its own `getDownloadUrl`/`DownloadOpener.open`
141	  /// pair in flight at once. Keyed per-format (review finding, round 2 —
142	  /// a single shared flag silently dropped a legitimate, concurrent tap on
143	  /// the *other* format's button while the first was still in flight,
144	  /// since both "Baixar PDF"/"Baixar dados brutos" can be enabled at the
145	  /// same time in the `narrativeReady` outcome) so the two formats never
146	  /// block each other. A second call for an already-in-flight format is a
147	  /// no-op — resolves to `null` (no failure to surface) without touching
148	  /// the repository or the opener at all.
149	  final Set<ExportDownloadFormat> _downloadsInFlight = {};
150	
151	  static const _downloadFailureMessage = 'Não foi possível abrir o arquivo.';
152	
153	  /// "Baixar PDF" — see [_download].
154	  Future<Failure?> downloadPdf() => _download(ExportDownloadFormat.pdf);
155	
156	  /// "Baixar dados brutos" — see [_download].
157	  Future<Failure?> downloadRawData() => _download(ExportDownloadFormat.raw);
158	
159	  /// Resolves [format]'s signed download URL (`export-download-get`) and
160	  /// hands it to [_downloadOpener] to open externally — never buffered in
161	  /// this app (Boundaries). Returns `null` on success, or the `Failure`
162	  /// that explains why otherwise — `ExportStatusSheet._handleDownload`
163	  /// awaits this return value directly, rather than reading it back off a
164	  /// side-channel field (review finding: a shared mutable field, written
165	  /// by the cubit and mutated by the widget, broke encapsulation and was
166	  /// racy before [_downloadsInFlight] existed).
167	  Future<Failure?> _download(ExportDownloadFormat format) async {
168	    if (_downloadsInFlight.contains(format)) {
169	      return null;
170	    }
171	    _downloadsInFlight.add(format);
172	    try {
173	      final jobId = _jobId;
174	      if (jobId == null) {
175	        // Shouldn't happen — every download button only ever renders once
176	        // `start()` has already stored a jobId — but silently reporting
177	        // success here would be indistinguishable from a real one
178	        // (review finding, patch item 4).
179	        return const Failure.malformedResponse(
180	          message: _downloadFailureMessage,
181	        );
182	      }
183	      final result = await _repository.getDownloadUrl(jobId, format: format);
184	      // Review finding (round 2) — [_downloadOpener.open] is a pure
185	      // side-effect handoff to the OS; it never touches [state]/[emit], so
186	      // there's no encapsulation reason to skip it once [isClosed] (unlike
187	      // [_poll]'s own `isClosed` guard, which exists specifically to avoid
188	      // emitting after disposal). Short-circuiting here used to silently
189	      // drop the user's download the instant they dismissed the sheet.
190	      return await result.match((failure) async => failure, (url) async {
191	        try {
192	          final opened = await _downloadOpener.open(url);
193	          return opened
194	              ? null
195	              : const Failure.malformedResponse(
196	                  message: _downloadFailureMessage,
197	                );
198	        } catch (_) {
199	          // [DownloadOpener]'s own contract never promises it won't throw
200	          // — the real `UrlLauncherDownloadOpener` already catches
201	          // internally, but nothing enforces that on the port itself
202	          // (review finding, patch item 5). RNF09: never let a thrown
203	          // exception escape uncaught out of `_handleDownload`'s own
204	          // unguarded `await`.
205	          return const Failure.malformedResponse(
206	            message: _downloadFailureMessage,
207	          );
208	        }
209	      });
210	    } finally {
211	      _downloadsInFlight.remove(format);
212	    }
213	  }
214	
215	  @override
216	  Future<void> close() {
217	    _pollTimer?.cancel();
218	    return super.close();
219	  }
220	}
221

