22	/// Same shape as `capture_flow_e2e_test.dart`'s/`chat_flow_e2e_test.dart`'s
23	/// own fake adapter — only the transport boundary is faked.
24	class _FakeHttpClientAdapter implements HttpClientAdapter {
25	  final List<RequestOptions> requests = [];
26	  final List<
27	    ({int statusCode, Map<String, dynamic>? body, Map<String, String>? headers})
28	  >
29	  _queue = [];
30	
31	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
32	    _queue.add((statusCode: statusCode, body: body, headers: null));
33	  }
34	
35	  /// spec-7-2 review patch (item 8) — queues a `302` with no JSON body,
36	  /// just a `Location` header, mirroring `export-download-get`'s own real
37	  /// shape (`openapi.yaml`: "302: Redirect to a signed Storage URL").
38	  void queueRedirectResponse(String location) {
39	    _queue.add((statusCode: 302, body: null, headers: {'location': location}));
40	  }
41	
42	  @override
43	  Future<ResponseBody> fetch(
44	    RequestOptions options,
45	    Stream<Uint8List>? requestStream,
46	    Future<void>? cancelFuture,
47	  ) async {
48	    requests.add(options);
49	    if (_queue.isEmpty) {
50	      throw StateError(
51	        'No queued response for ${options.method} ${options.path}',
52	      );
53	    }
54	    final next = _queue.removeAt(0);
55	    final body = next.body;
56	    return ResponseBody.fromString(
57	      body != null ? jsonEncode(body) : '',
58	      next.statusCode,
59	      headers: {
60	        if (body != null) Headers.contentTypeHeader: [Headers.jsonContentType],
61	        ...next.headers?.map((key, value) => MapEntry(key, [value])) ?? {},
62	      },
63	    );
64	  }
65	
66	  @override
67	  void close({bool force = false}) {}
68	}
