114	/// Waits for [cubit]'s state to satisfy [match], via the cubit's own
115	/// `stream` rather than a fixed real-time sleep keyed to the exact 2s poll
116	/// cadence (`ExportJobCubit._pollInterval`) — resolves immediately if
117	/// already true. The timeout only ever fires if the poll loop is
118	/// genuinely broken, turning a hang into a fast, clear test failure.
119	Future<void> _waitForState(
120	  ExportJobCubit cubit,
121	  bool Function(ExportJobState) match,
122	) {
123	  if (match(cubit.state)) {
124	    return Future.value();
125	  }
126	  return cubit.stream.firstWhere(match).timeout(const Duration(seconds: 10));
127	}
